const reconItems = [
["opening-2028-a",1,null,"איזה מהבאים נחשב מרכיב חיוני בבדיקה הגופנית של מטופל עם מסה בצוואר, בהתאם לקטע?",["הערכה של כל משטחי הרירית באמצעות flexible fiberoptic laryngoscopy, ומישוש של רצפת הפה, הלשון, ריריות הלחי, החך, עמודי השקדים והשקדים","בדיקה ויזואלית בלבד ללא מישוש","בדיקת המסה בלבד, ללא בדיקה של ה-aerodigestive tract","הערכה של בסיס הצוואר בלבד, למניעת כאב למטופל"],0,"מסה בצוואר במבוגר יכולה להיות גרורה של גידול ראשוני בחלל הפה, בלוע או בלרינקס. לכן הבדיקה חייבת לכלול את כל ה-upper aerodigestive tract, ולא רק את המסה עצמה. נוסח השאלה שוחזר מצילום מטושטש.",["זו בדיקה שלמה: מישוש של כל אתרי חלל הפה, ולרינגוסקופיה גמישה שמראה את הנזופרינקס, האורופרינקס, ההיפופרינקס והלרינקס. שם מסתתר לעיתים קרובות הגידול הראשוני.","הסתכלות בלבד מפספסת נגעים תת-ריריים ונגעים בבסיס הלשון, שמתגלים בעיקר במישוש.","בדיקת המסה לבדה לא מאתרת את המקור. מציאת הגידול הראשוני היא לב הבירור.","נוחות המטופל לא מצדיקה בדיקה חלקית. בסיס הצוואר הוא רק אזור אחד מתוך רבים שצריך לבדוק."]],
 ["opening-2028-a",2,null,"מטופל בן 62 מגיע עם מסה בצוואר שהופיעה לפני חודש וממשיכה לגדול באופן עקבי. אין סימני זיהום. מהי הגישה הנכונה ביותר על פי העקרונות המתוארים בקטע?",["לבצע מעקב בלבד במשך 3 חודשים כדי להעריך יציבות","להניח שהמסה ממאירה עד שיוכח אחרת, מאחר שמבוגרים נמצאים בסיכון גבוה לממאירות","להניח שמדובר בזיהום ולתת אנטיביוטיקה אמפירית","להתייחס למסה כשפירה עד שיוכח אחרת, מאחר שמסות צוואר שכיחות בגיל מבוגר"],1,"הכלל המרכזי: מסה בצוואר במבוגר נחשבת ממאירה עד שיוכח אחרת. מסה שגדלה בהתמדה בלי סימני זיהום מחזקת את החשד ומחייבת בירור מיידי: בדיקת ראש-צוואר מלאה, הדמיה ו-FNA.",["מעקב של 3 חודשים מעכב אבחנה של ממאירות. מסה שגדלה כבר חודש צריכה בירור עכשיו.","זה הכלל. בגיל 62 ובמסה שגדלה, ההנחה הבטוחה היא ממאירות עד שהבירור מוכיח אחרת.","אין סימני זיהום, ואנטיביוטיקה אמפירית רק דוחה את הבירור. גם כשנותנים ניסיון אנטיביוטי, מסה שלא נעלמת תוך כשבועיים מחייבת בירור.","זה הפוך: בילדים רוב המסות שפירות (דלקתיות או מולדות), ובמבוגרים שיעור הממאירות גבוה."]],
 ["opening-2028-a",3,null,"לאן מתנקזים הסינוסים הפרונטליים?",["המיאטוס העליון","הקואנות","הספנו-אתמואיד רסס","המיאטוס האמצעי"],3,"הסינוס הפרונטלי מתנקז דרך ה-frontal recess אל המיאטוס האמצעי. לשם מתנקזים גם הסינוס המקסילרי והתאים האתמואידליים הקדמיים, באזור שנקרא ostiomeatal complex.",["למיאטוס העליון מתנקזים התאים האתמואידליים האחוריים.","הקואנות הן הפתחים האחוריים של חלל האף אל הנזופרינקס. הן לא אתר ניקוז של סינוס.","לספנו-אתמואיד רסס מתנקז הסינוס הספנואידלי.","נכון. פרונטלי, מקסילרי ואתמואידים קדמיים מתנקזים כולם למיאטוס האמצעי."]],
 ["opening-2028-a",4,null,"מטופל בן 25 מגיע למיון עם כאב גרון חמור מזה יומיים, שהחמיר מאוד מצד ימין. הוא מתקשה לפתוח את הפה, הקול שלו נשמע כמו \"תפוח אדמה לוהט\", והענבל סוטה שמאלה. מהי האבחנה הסבירה?",["מונונוקלאוזיס EBV","דלקת גרון סטרפטוקוקלית חריפה","לרינגיטיס חריפה","אבצס פריטונסילארי"],3,"כאב גרון חד-צדדי קשה, טריזמוס, קול hot potato וסטיית ענבל לצד הנגדי הם התמונה הקלאסית של אבצס פריטונסילארי (quinsy). הטיפול הוא ניקוז ואנטיביוטיקה.",["במונו הכאב דו-צדדי, השקדים מוגדלים עם תפליט, יש קשריות צוואר אחוריות ועייפות. בדרך כלל אין טריזמוס ואין סטיית ענבל.","בסטרפ הדלקת דו-צדדית, בלי טריזמוס ובלי סטיית ענבל. אבצס פריטונסילארי יכול להיות סיבוך שלה.","לרינגיטיס גורמת לצרידות ושיעול, לא לטריזמוס ולא לסטיית ענבל.","נכון. האבצס שבין קופסית השקד לשרירי הלוע דוחף את השקד והענבל לצד השני, וגירוי שריר ה-medial pterygoid גורם לטריזמוס."]],
 ["opening-2028-a",5,null,"מהו הגבול האחורי של חלל האף?",["הקואנות","הטורבינה האמצעית","הסינוס הפרונטלי","מחיצת האף"],0,"חלל האף נפתח מאחור אל הנזופרינקס דרך הקואנות (choanae). זה הגבול האחורי שלו.",["נכון. הקואנות מחברות את חלל האף לנזופרינקס.","הטורבינה האמצעית היא מבנה בדופן הצידית של חלל האף.","הסינוס הפרונטלי נמצא בעצם המצח, מעל ומלפנים. הוא לא גבול של חלל האף.","המחיצה היא הגבול המדיאלי, והיא מפרידה בין שני צידי האף."]],
 ["opening-2028-a",6,null,"מהי המטרה בניתוח בשל מחלת כולסטאטומה?",["סילוק המחלה ויצירת אוזן בטוחה","הפסקת ההפרשה מהאוזן","שיפור השמיעה","שיפור שיווי המשקל"],0,"כולסטאטומה מתקדמת והורסת עצם, ועלולה לגרום לסיבוכים קשים: שיתוק עצב הפנים, פיסטולה לבירינתית, דלקת קרום המוח ואבצס מוחי. לכן המטרה הראשונה היא הוצאה מלאה של המחלה ואוזן בטוחה ויבשה.",["נכון. כל שאר המטרות באות אחרי סילוק המחלה.","הפרשה שנפסקת היא תוצאה רצויה, אבל היא משנית לסילוק המחלה.","שיפור שמיעה הוא מטרה משנית, ולעיתים נעשה בשלב שני של שחזור שרשרת העצמות. לפעמים השמיעה אפילו נפגעת בניתוח.","שיווי משקל אינו מטרת הניתוח. פיסטולה לבירינתית היא סיבוך שמטפלים בו כחלק מסילוק המחלה."]],
 ["opening-2028-a",7,null,"מהו המקור העיקרי של אספקת הדם לאזור קיסלבך?",["העורק הספנופלטיני","העורק האנטריורי אתמואידלי","תרומה משולבת של מספר עורקים","העורק הפציאלי"],2,"אזור קיסלבך (Little's area), בחלק הקדמי-תחתון של המחיצה, הוא מקלעת של אנסטומוזות בין כמה עורקים: anterior ethmoidal (מה-ICA), sphenopalatine, greater palatine ו-superior labial (מה-ECA). מכאן מגיעים כ-90% מהדימומים מהאף.",["הספנופלטיני הוא אחד המרכיבים, ומקור עיקרי לדימום אחורי, אבל לא המקור היחיד של המקלעת.","האתמואידלי הקדמי תורם למקלעת, אבל גם הוא רק חלק ממנה.","נכון. זו מקלעת שכל כוחה הוא בחיבור של כמה עורקים.","הפציאלי תורם דרך ה-superior labial בלבד, כלומר רק חלק מהמקלעת."]],
 ["opening-2028-a",8,null,"איזה מהגורמים הבאים הוא גורם סיכון לדלקת אוזן תיכונה?",["עישון פסיבי","הנקה","מין נקבה","משקל עודף"],0,"גורמי הסיכון הקלאסיים ל-AOM: עישון פסיבי, מעון יום, גיל צעיר, מוצץ, האכלה מבקבוק בשכיבה, אחים בבית, היסטוריה משפחתית וחך שסוע.",["נכון. עשן סיגריות פוגע בפינוי הרירי-ריסני ובתפקוד החצוצרה.","הנקה דווקא מגינה, בזכות נוגדנים מהאם ותנוחת האכלה טובה יותר.","AOM שכיחה מעט יותר בבנים, לא בבנות.","משקל עודף אינו גורם סיכון קלאסי ל-AOM."]],
 ["opening-2028-a",9,null,"מהו הגורם השכיח ביותר לדלקת אוזן חיצונית?",["Pseudomonas aeruginosa","Staphylococcus epidermidis","Moraxella catarrhalis","Streptococcus pneumoniae"],0,"Pseudomonas aeruginosa הוא הגורם השכיח ביותר ל-otitis externa חריפה, ואחריו Staphylococcus aureus.",["נכון. הוא אוהב סביבה לחה, ולכן הדלקת נקראת גם \"אוזן של שחיינים\".","Staph epidermidis הוא חלק מהפלורה הרגילה של העור, ובדרך כלל אינו פתוגן כאן.","Moraxella היא גורם שכיח ל-AOM ולסינוסיטיס, לא לאוזן חיצונית.","Strep pneumoniae הוא הגורם השכיח לדלקת אוזן תיכונה, לא חיצונית."]],
 ["opening-2028-a",10,null,"מהו הממצא בבדיקת חלל הפה שנחשב \"דגל אדום\" ומחייב הפניה לביופסיה בחשד לממאירות?",["אפטה כואבת בקוטר 0.5 ס\"מ שמופיעה פעם בחודש","כיב שאינו מחלים במשך 3 שבועות, עם שוליים מורמים וקשים","פטרייה לבנה על הלשון הניתנת לגירוד בקלות","אודם על החיך הרך, מלווה בחום וכאב גרון"],1,"כיב בחלל הפה שלא מחלים תוך 2–3 שבועות, במיוחד עם שוליים מורמים ומוקשים (induration), חשוד ל-SCC ומחייב ביופסיה.",["אפטה היא קטנה, כואבת, חוזרת ומחלימה תוך 1–2 שבועות. הדפוס החוזר מתאים לסטומטיטיס אפטית.","נכון. אי-החלמה, שוליים מורמים והתקשות הם סימני האזהרה לגידול.","נגע לבן שמתגרד הוא קנדידה. דווקא נגע לבן שלא מתגרד (לויקופלקיה) חשוד.","אודם עם חום וכאב גרון מתאים לזיהום חריף."]],
 ["opening-2028-a",11,null,"מטופל בן 55, מעשן כבד, מגיע למרפאה עקב צרידות שנמשכת 6 שבועות, ללא תסמינים נוספים. מהו הצעד הבא?",["המלצה על הפסקת עישון ומנוחה קולית, ומעקב בעוד חודש","התחלת טיפול ב-PPI בחשד לרפלוקס","מתן קורס סטרואידים פומיים להורדת הבצקת","הפנייה דחופה לבדיקת לרינגוסקופיה אצל רופא אא\"ג"],3,"צרידות שנמשכת יותר מ-3–4 שבועות, ובמעשן כבד גם מוקדם יותר, מחייבת לראות את המיתרים ישירות כדי לשלול סרטן של הלרינקס.",["הפסקת עישון חשובה, אבל לדחות בחודש נוסף בלי בדיקה זה מסוכן.","PPI אמפירי בלי לראות את הלרינקס עלול להסוות גידול.","סטרואידים לא מומלצים לצרידות בלי אבחנה, ועלולים לטשטש את התמונה.","נכון. מעשן עם צרידות מתמשכת צריך לרינגוסקופיה בהקדם."]],
 ["opening-2028-a",12,null,"מטופל מגיע עם מסה בצוואר, והרופא מנסה לקבוע אם היא supraplatysmal או subplatysmal, וכן אם מיקומה קדמי או צידי. לפי העקרונות בקטע, למה חשובה קביעה זו?",["היא קובעת באופן חד-משמעי אם מדובר בממאירות","היא מאפשרת לקבוע את הצורך ב-PET-CT בלבד","היא מסייעת בהכוונת ה-differential diagnosis ובבחירה יעילה של בדיקות אבחנתיות משלימות"],2,"מיקום המסה ביחס לפלטיזמה (שטחית או עמוקה) ובצוואר (קדמי או צידי) מצמצם את האבחנה המבדלת. למשל: מסה שטחית מתאימה לציסטה דרמואידית או ליפומה; מסה עמוקה וצידית לקשרית לימפה, ציסטה ברנכיאלית או גידול נוירוגני; מסה קדמית באמצע לציסטה של thyroglossal או לבלוטת התריס. בצילום נראו רק 3 אפשרויות. ייתכן שאפשרות ד' נחתכה.",["מיקום לבד לא קובע אם יש ממאירות. לשם כך צריך ביופסיה (FNA).","PET-CT אינו בדיקה ראשונית, וההחלטה עליו לא נקבעת לפי מיקום בלבד.","נכון. המיקום מכוון לאבחנה המבדלת ולבדיקות המתאימות."]],
 ["opening-2028-b",1,null,"מהו הממצא האופייני בדלקת אוזן תיכונה חריפה?",["אוזן יבשה","רטרקציה של עור התוף","עור תוף בולט","נקב בעור התוף"],2,"ב-AOM עור התוף בולט (bulging), אדום ולא זז בפנאומטוסקופיה, ומאחוריו נוזל מוגלתי. הבליטה היא הסימן הספציפי ביותר.",["באוזן תיכונה דלקתית יש נוזל, כך שאוזן יבשה לא מתאימה.","רטרקציה מאפיינת תפקוד לקוי של החצוצרה ו-OME כרוני, לא AOM.","נכון. עור תוף בולט הוא הממצא האופייני.","נקב יכול להופיע כסיבוך של AOM, עם הפרשה, אבל הוא לא הממצא האופייני."]],
 ["opening-2028-b",2,null,"סטודנטית בת 20 מגיעה עם כאב גרון, חום ותשישות קיצונית מזה שבוע. בבדיקה רואים \"שקדים נושקים\" וקשריות לימפה מוגדלות בעיקר בשרשרת הצווארית האחורית. מהי האבחנה הסבירה?",["אבצס פריטונסילארי","דלקת גרון סטרפטוקוקלית","הרפס","מונונוקלאוזיס"],3,"מבוגרת צעירה עם חום, כאב גרון, עייפות קיצונית, שקדים מוגדלים מאוד וקשריות צוואר אחוריות: זו התמונה של מונונוקלאוזיס (EBV). ייתכנו גם הגדלת טחול וכבד. האבחנה בבדיקת Monospot או סרולוגיה, ובספירה רואים לימפוציטים אטיפיים.",["אבצס פריטונסילארי הוא חד-צדדי, עם טריזמוס וסטיית ענבל.","בסטרפ הקשריות הן קדמיות ורגישות. עייפות קיצונית וקשריות אחוריות פחות אופייניות.","הרפס גורם לשלפוחיות ולכיבים בחלל הפה (gingivostomatitis), לא לשקדים ענקיים.","נכון. קשריות אחוריות ועייפות קיצונית הן הרמז המכריע."]],
 ["opening-2028-b",3,null,"מה חשוב לשלול בכל מטופל עם חבלה לאף?",["סטיית מחיצה","דלקת סינוסים","דלקת בלוע","המטומה ספטלית ופגיעות ארובה"],3,"בכל חבלה לאף בודקים את המחיצה כדי לשלול המטומה ספטלית: נפיחות רכה וכחלחלה של המחיצה. אם לא מנקזים אותה בזמן, היא עלולה לגרום לנמק של הסחוס, לאבצס ולעיוות של אף אוכף (saddle nose). בנוסף שוללים פגיעה בארובה: שבר blow-out, הגבלה בתנועות העיניים, ראייה כפולה או פגיעה בראייה.",["סטיית מחיצה יכולה להיגרם מחבלה, אבל היא לא מצב דחוף. מטפלים בה אלקטיבית.","דלקת סינוסים אינה הסכנה המיידית אחרי חבלה.","דלקת בלוע לא קשורה לחבלה באף.","נכון. אלה שני הסיבוכים שמחייבים טיפול מהיר."]],
 ["opening-2028-b",4,null,"איזה מבין הבאים מאפיין כולסטאטומה מולדת?",["היסטוריה של דלקות חוזרות","הופעה בגיל מבוגר","נקב בעור התוף","עור תוף תקין"],3,"כולסטאטומה מולדת נראית כמסה לבנה (\"פנינה\") מאחורי עור תוף שלם, לרוב ברבע הקדמי-עליון, בילד בלי היסטוריה של דלקות, ניתוחים או נקב.",["דלקות חוזרות מאפיינות כולסטאטומה נרכשת.","כולסטאטומה מולדת מתגלה בדרך כלל בילדות, סביב גיל 4–5.","נקב מאפיין כולסטאטומה נרכשת. במולדת עור התוף שלם.","נכון. עור תוף שלם הוא אחד מתנאי ההגדרה."]],
 ["opening-2028-b",5,null,"מהי הסיבה השכיחה ביותר לסינוסיטיס חריפה?",["זיהום חיידקי ראשוני","זיהום ויראלי, כמו רינווירוס או אינפלואנזה","חסימה מכנית של המיאטוס האמצעי","תגובה אלרגית בלבד"],1,"רוב מקרי הסינוסיטיס החריפה הם ויראליים, ורק כ-0.5–2% מסתבכים בזיהום חיידקי. חושדים בחיידק כשהתסמינים נמשכים יותר מ-10 ימים, כשיש החמרה אחרי שיפור (double worsening), או כשהתסמינים קשים.",["זיהום חיידקי הוא בדרך כלל משני לזיהום ויראלי, לא ראשוני.","נכון. הסיבה השכיחה היא ויראלית.","חסימה של ה-ostiomeatal complex היא חלק מהמנגנון (בצקת בעקבות הזיהום), לא הסיבה השכיחה עצמה.","אלרגיה יכולה לתרום, אבל אינה הסיבה השכיחה לסינוסיטיס חריפה."]],
 ["opening-2028-b",6,null,"מהו המנגנון העיקרי שמונע אספירציה במהלך הבליעה?",["הרפיה של סוגר הוושט העליון","עלייה של החיך הרך לסגירת הנזופרינקס","כיווץ השרירים הקונסטריקטורים של הלוע","עלייה של הלרינקס קדימה ולמעלה, סגירת האפיגלוטיס לאחור וסגירת המיתרים"],3,"בשלב הלועי של הבליעה דרכי האוויר מוגנות כך: הלרינקס עולה קדימה ולמעלה אל מתחת לבסיס הלשון, האפיגלוטיס מתקפל מעל הכניסה ללרינקס, ומיתרי הקול נסגרים.",["פתיחת הסוגר העליון מאפשרת למזון לעבור לוושט, אבל לא מגינה על דרכי האוויר.","עליית החך מונעת מעבר של מזון לאף, לא אספירציה לקנה.","הקונסטריקטורים דוחפים את הבולוס למטה, אבל לא סוגרים את דרכי האוויר.","נכון. זה המנגנון שמגן על הקנה."]],
 ["opening-2028-b",7,null,"מהו המשפט הנכון לגבי תאי עצב הריח?",["חלקיקי הריח מתחברים לקולטנים בריסים לאחר שהם נמסים ברירית","האות מהרירית עובר ישירות לקורטקס ללא תחנת ביניים","כל תא ריח מבטא מספר גנים שמאפשרים זיהוי של ריחות רבים","תאי עצב הריח אינם מתחדשים לאורך החיים"],0,"מולקולות הריח חייבות קודם להתמוסס בשכבת הריר שמכסה את אפיתל הריח, ורק אז הן נקשרות לקולטנים שעל הריסים של נוירוני הריח.",["נכון. ההתמוססות בריר היא שלב הכרחי לפני הקישור לקולטן.","האות עובר קודם בבולבוס הריח, שם יש סינפסה עם תאי ה-mitral. המסלול עוקף את התלמוס, אבל הבולבוס הוא תחנת ביניים.","כל נוירון ריח מבטא סוג אחד בלבד של קולטן (one neuron, one receptor).","נוירוני הריח מתחדשים כל החיים מתאי הבסיס (basal cells), מקרה נדיר של נוירוגנזה במבוגר."]],
 ["opening-2028-b",8,null,"ילדה בת 8 מגיעה עם מסה בצוואר. הרופא שוקל איזו הדמיה להזמין תחילה. בהתאם לעקרונות בקטע, מהי המודליות המתאימה ביותר להדמיה ראשונית?",["Ultrasonography, מאחר שהיא נטולת קרינה ומסוגלת להבדיל בין מסות מוצקות למלאות נוזל","תהודה מגנטית (MRI) עם gadolinium","טומוגרפיה ממוחשבת (CT) עם חומר ניגוד","PET-CT, לצורך הדמיה תפקודית ראשונית"],0,"בילדים US הוא ההדמיה הראשונית למסה בצוואר: בלי קרינה, בלי הרדמה, זמין, מבדיל בין ציסטי למוצק ומראה גם את בלוטת התריס.",["נכון. בטוח, זמין ומספק את המידע שצריך בשלב הראשון.","MRI מצוין לרקמות רכות, אבל בילדים הוא לרוב מחייב הרדמה או סדציה ויקר. הוא לא הבדיקה הראשונה.","CT כרוך בקרינה, שמשתדלים להימנע ממנה בילדים. שומרים אותו למצבים כמו אבצס עמוק או חשד לממאירות.","PET-CT אינו בדיקה ראשונית. משתמשים בו לשלב ולמעקב בממאירות."]],
 ["opening-2028-b",9,null,"מהו הממצא האופייני בדלקת אוזן תיכונה כרונית ללא כולסטאטומה?",["נקב בעור התוף והפרשה","עור תוף תקין","בצקת בתעלת השמע","עור תוף בולט"],0,"CSOM בלי כולסטאטומה (הסוג הרירי) מתבטאת בנקב קבוע בעור התוף עם הפרשה חוזרת או מתמשכת מהאוזן התיכונה, בדרך כלל בלי כאב.",["נכון. נקב והפרשה הם הסימן המזהה.","עור תוף תקין לא מתאים לדלקת כרונית פעילה מהסוג הזה.","בצקת בתעלת השמע מתאימה לדלקת אוזן חיצונית.","עור תוף בולט מאפיין דלקת אוזן תיכונה חריפה."]],
 ["opening-2028-b",10,null,"ילד בן 6 מגיע עם מסה אמצעית בצוואר. בבדיקה המסה רכה, ציסטית וממוקמת מעט מתחת לעצם ההיואיד. איזה ממצא נוסף בבדיקה הוא הכי אופייני ל-Thyroglossal Duct Cyst?",["המסה עולה מעלה בזמן הבלטת הלשון (tongue protrusion)","המסה פועמת ורכה","המסה ממוקמת קדמית ל-sternocleidomastoid ונפתחת ל-tonsillar fossa","המסה גדלה בזמן Valsalva maneuver"],0,"ציסטה של thyroglossal duct היא שארית של מסלול הירידה של בלוטת התריס מה-foramen cecum. היא קשורה לבסיס הלשון ולעצם ההיואיד, ולכן עולה כשמוציאים לשון וכשבולעים. הטיפול הוא ניתוח Sistrunk, שכולל כריתה של החלק האמצעי של ההיואיד.",["נכון. התנועה עם הלשון היא הסימן הקלאסי.","מסה פועמת מעלה חשד למקור כלי דם, למשל carotid body tumor.","מיקום קדמי ל-SCM עם פתח ל-tonsillar fossa מתאים לציסטה ברנכיאלית מסוג 2, שהיא מסה צידית ולא אמצעית.","מסה שגדלה ב-Valsalva מתאימה ללרינגוצלה."]],
 ["opening-2028-b",11,null,"מטופל מבוגר מגיע עם מסה בבלוטת הפרוטיד, וה-CT לא מאפיין היטב את גבולות המסה. לפי העקרונות בקטע, מהי ההדמיה המתאימה ביותר להמשך הבירור?",["MRI, שמספק את המידע האנטומי המפורט ביותר על רקמות רכות ומועיל במיוחד במסות של בלוטות רוק","CT נוסף עם חומר ניגוד בריכוז גבוה","PET-CT, מאחר שהוא כלי הבחירה לזיהוי הגידול הראשוני","CTA, מאחר שהיא מאפשרת הערכה של נגעים שאינם וסקולריים"],0,"MRI הוא בדיקת הבחירה לגידולי בלוטות רוק, ובמיוחד הפרוטיד. הוא מגדיר גבולות, חדירה לרקמות, מעורבות של עצב הפנים והתפשטות לאורך עצבים (perineural spread), ומבחין בין האונה השטחית לעמוקה.",["נכון. MRI נותן את ההפרדה הטובה ביותר של רקמות רכות.","CT נוסף לא ישפר משמעותית את ההפרדה של רקמות רכות, ומוסיף קרינה.","PET-CT משמש לשלב ולחיפוש גרורות, לא לאפיון מקומי. גם גידולים שפירים כמו Warthin קולטים בו.","CTA נועדה להדמיית כלי דם, ולא רלוונטית כשאין חשד לנגע וסקולרי."]],
 ["opening-2028-b",12,null,"איזה מהסימנים הבאים הופך אבחנה של דלקת גרון חיידקית לפחות סבירה ומכוון יותר לאטיולוגיה ויראלית?",["קשריות לימפה קדמיות רגישות","חום גבוה מעל 38.5","שיעול ונזלת","תפליטים פוליקולריים על פני השקדים"],2,"לפי קריטריוני Centor/McIsaac, הסימנים לסטרפ הם: חום מעל 38, קשריות צוואר קדמיות רגישות, תפליט על השקדים והיעדר שיעול. שיעול, נזלת, צרידות ודלקת לחמית מכוונים לגורם ויראלי.",["קשריות קדמיות רגישות הן נקודה בעד סטרפ.","חום מעל 38 הוא נקודה בעד סטרפ.","נכון. שיעול ונזלת מורידים את הסבירות לחיידק.","תפליט על השקדים הוא נקודה בעד סטרפ, אם כי הוא מופיע גם ב-EBV ובאדנווירוס."]],
 ['final-form-d',2,1,'הטיפול המומלץ לדלקת אוזן תיכונה חריפה ראשונה בילד בן 3 שלא ידועה אצלו רגישות לתרופות?', ['אמוקסיצילין 90 מ״ג/ק״ג לחלק ל־2 מנות ביום למשך 10 ימים','רספרים 8 מ״ג/ק״ג לחלק ל־2 מנות ליום ל־7 ימים','קלינדמיצין 30–40 מ״ג/ק״ג לחלק ל־2–3 מנות ליום למשך 7 ימים','אזניל 10 מ״ג/ק״ג פעם ביום למשך 5 ימים'],0,'קו ראשון ב־AOM הוא Amoxicillin במינון גבוה (80–90 מ״ג/ק״ג ליום בשתי מנות), כדי לכסות גם פנאומוקוק עם עמידות חלקית. בגיל 3 ובאירוע ראשון משך הטיפול המקובל הוא 10 ימים.', ['זה הטיפול המומלץ.','רספרים אינו קו ראשון ב־AOM, ויש עמידות גבוהה אליו.','קלינדמיצין שמור למצבים מיוחדים, למשל אלרגיה, ולא לקו ראשון.','אזיתרומיצין אינו קו ראשון ב־AOM.']],
 ['final-form-d',4,1,'מה נכון לגבי תינוק עם CMV מולד (congenital CMV)?', ['הימצאות DNA של הנגיף בשתן של התינוק בגיל חודש היא אבחנתית','ליקוי שמיעה עלול להתרחש גם כשאין פגיעה נוירולוגית נוספת','הידרדרות בשמיעה תהיה כמעט תמיד מיידית','תרופות כמו Ganciclovir יעילות בטיפול בפגיעה נוירולוגית אך לא בפגיעה בשמיעה'],1,'CMV מולד הוא הגורם הלא־גנטי השכיח לירידת שמיעה תחושתית־עצבית בילדים. ירידת השמיעה יכולה להופיע גם בתינוק שנראה אסימפטומטי, ולעתים היא מתקדמת או מופיעה רק מאוחר יותר.', ['כדי להוכיח הדבקה מולדת צריך לזהות את הנגיף בשלושת השבועות הראשונים לחיים. אחרי זה אי אפשר להבדיל בינה לבין הדבקה אחרי הלידה.','זו התשובה הנכונה. גם בלי ממצאים נוירולוגיים אחרים יכולה להיות ירידת שמיעה.','הירידה יכולה להיות מאוחרת או מתקדמת, ולכן ממשיכים במעקב שמיעה.','טיפול אנטי־ויראלי (Ganciclovir או Valganciclovir) נועד בין השאר לשפר את תוצאות השמיעה.']],
 ['final-form-d',6,2,'באיזו בלוטת רוק שכיחות היווצרות האבנים היא הגדולה ביותר?', ['בלוטת הפרוטיס','הבלוטה התת־לסתית','הבלוטה התת־לשונית','בלוטת רוק מינורית'],1,'כ־80% מאבני הרוק נמצאות בבלוטה התת־לסתית. הרוק שלה צמיג ובסיסי יותר ועשיר בסידן, והצינור שלה (Wharton) ארוך ועולה כלפי מעלה נגד כוח המשיכה.', ['בפרוטיס יש פחות אבנים, כי הרוק שלה סרוזי ומימי יותר.','זו התשובה הנכונה.','אבנים בבלוטה התת־לשונית נדירות.','אבנים בבלוטות מינוריות נדירות מאוד.']],
 ['final-form-d',9,2,'מה נכון לגבי גידול T1 SCC במיתר קול?', ['ניתן לטפל בקרינה מקומית או בכריתה אנדוסקופית של הגידול','הטיפול המומלץ הוא קרינה בשילוב כימותרפיה','הטיפול המומלץ הוא כריתה אנדוסקופית של הגידול וביצוע דיסקציה צווארית','במידה ויש חזרה לאחר ניתוח אנדוסקופי, האופציה המועדפת היא כריתת גרון שלמה'],0,'סרטן גלוטי מוקדם (T1) מטופל בשיטה אחת: קרינה או כריתה אנדוסקופית (למשל בלייזר). שיעורי ההחלמה גבוהים מאוד. בגלוטיס יש מעט ניקוז לימפטי, ולכן גרורות צוואריות בשלב הזה נדירות.', ['זו התשובה הנכונה.','כימותרפיה שמורה לשלבים מתקדמים.','בגידול גלוטי T1 אין צורך בדיסקציה צווארית, כי גרורות לקשרים נדירות.','בחזרה אחרי ניתוח אנדוסקופי יש אפשרויות שמשמרות את הגרון, כמו כריתה חוזרת או קרינה. כריתת גרון שלמה אינה בהכרח הבחירה הראשונה.']],
 ['final-form-d',10,3,'אישה בת 50 פונה בשל חסימה אפית חד־צדדית, דמם אפי חוזר בשבועות האחרונים וירידה בשמיעה בצד ימין. אין היסטוריה רפואית ראויה לציון. בבדיקתה נצפו נוזלים באוזן התיכונה מימין ומסה בנזופרינקס. מה הצעד הבא?', ['טיפול סטרואידלי מקומי בתרסיס ותרופות מפחיתות גודש','ביופסיה מהנזופרינקס','אנטיביוטיקה וסטרואידים באבחנה של סינוסיטיס','הפניה לבדיקת שמיעה דחופה בשל ירידת שמיעה חד־צדדית'],1,'במבוגר, נוזל חד־צדדי באוזן התיכונה מחייב לבדוק את הנזופרינקס, כי גידול שם יכול לחסום את פתח החצוצרה. כאן כבר נראית מסה, יחד עם חסימה ודימום חד־צדדיים, ולכן צריך ביופסיה כדי לשלול קרצינומה נזופרינגיאלית.', ['טיפול סימפטומטי מעכב אבחנה של גידול.','זה הצעד הנכון.','אין כאן תמונה של סינוסיטיס, ויש מסה שדורשת אבחנה.','הירידה בשמיעה נובעת מהנוזל באוזן. בדיקת שמיעה לא תסביר את המסה.']],
 ['final-form-d',13,3,'איזה מהבאים מתאר בצורה הטובה ביותר את הפתופיזיולוגיה של אוטוסקלרוזיס?', ['הרס אוטואימוני של השבלול','שינוי לא תקין של העצם בקפסולה האוטית (Otic capsule)','זיהום כרוני של האוזן התיכונה','גידול בתעלה השמיעתית הפנימית','הרס מיאלין של העצב הווסטיבולוקוכלארי CN VIII'],1,'באוטוסקלרוזיס יש בנייה מחדש לא תקינה של עצם הקפסולה האוטית, לרוב סביב חלון הסגלגל. הסטפס מתקבע, וזה גורם לירידת שמיעה הולכתית מתקדמת עם עור תוף תקין.', ['זה תיאור של מחלת אוזן פנימית אוטואימונית.','זו התשובה הנכונה.','באוטוסקלרוזיס האוזן התיכונה ועור התוף תקינים.','זה תיאור של שוואנומה וסטיבולרית.','זה לא המנגנון.']],
 ['final-form-d',17,4,'איזו תשובה נכונה בקשר לסרטן הלרינקס מסוג squamous cell carcinoma?', ['גידולים גלוטיים הם אגרסיביים מקומית ושולחים גרורות לבלוטות בצוואר בשלב מוקדם','המיקום השכיח ביותר לממאירות הלרינקס הוא תת־גלוטיס עם פרוגנוזה הכי גרועה','ההתסמנות הראשונית הנפוצה ביותר לממאירות בגרון היא קוצר נשימה וסטרידור','צרידות חדשה או שינוי בצרידות בחולה מעשן מעל שבועיים מחייבת בדיקת לרינקס','סיכויי החלמה בטיפול בגידול T1–2 על ידי ניתוח או קרינה דומים והם 50–65%'],3,'צרידות מתמשכת במעשן היא דגל אדום ומחייבת לראות את הלרינקס. גידולים גלוטיים מתגלים מוקדם, כי צרידות מופיעה כבר כשהם קטנים, ובגלוטיס יש מעט ניקוז לימפטי.', ['גידולים גלוטיים דווקא שולחים גרורות צוואריות מאוחר, בגלל מיעוט ניקוז לימפטי.','המיקום השכיח הוא הגלוטיס. תת־גלוטיס הוא האתר הנדיר ביותר.','הסימן הראשון השכיח הוא צרידות. סטרידור מעיד על מחלה מתקדמת.','זו התשובה הנכונה.','בגידול גלוטי T1 שיעורי ההחלמה גבוהים בהרבה, בסביבות 85–95%.']],
 ['final-form-d',18,5,'אילו מהתלונות הבאות אינה צפויה במטופל עם שיתוק מיתר קול שמאל בעקבות ניתוח המיתירואידקטומיה משמאל?', ['קוצר נשימה במאמץ','קוצר נשימה בדיבור','צרידות','שיעול בזמן שתיית מים','קושי בשיעול'],0,'כשמיתר אחד משותק, הגלוטיס לא נסגר עד הסוף. התוצאה: קול צרוד ונשיפתי, קוצר נשימה בדיבור (בריחת אוויר), שיעול בשתייה (אספירציה) ושיעול חלש. נתיב האוויר עצמו לרוב פתוח מספיק, ולכן קוצר נשימה במאמץ אינו צפוי. הוא אופייני יותר לשיתוק דו־צדדי.', ['זו התלונה שאינה צפויה, ולכן זו התשובה.','צפוי, בגלל בריחת אוויר דרך הגלוטיס הפתוח.','צפוי.','צפוי, בגלל אספירציה של נוזלים.','צפוי, כי בלי סגירה מלאה של הגלוטיס השיעול חלש.']],
 ['final-form-d',19,5,'מה מהבאים הוא סיבוך אפשרי של אבצס פריטונסילרי?', ['אבצס רטרופרינגיאלי','אפיגלוטיטיס','סינוסיטיס','דלקת אוזן תיכונה'],0,'הזיהום יכול להתפשט מהמרווח הפריטונסילרי למרווחים העמוקים בצוואר: הפרפרינגיאלי ומשם הרטרופרינגיאלי. מהרטרופרינגיאלי הוא יכול להגיע גם למדיאסטינום.', ['זו התשובה הנכונה.','אפיגלוטיטיס אינה סיבוך אופייני של אבצס פריטונסילרי.','אין קשר אנטומי ישיר לסינוסים.','דלקת אוזן תיכונה אינה סיבוך של אבצס פריטונסילרי.']],
 ['final-form-d',20,5,'מה מהבאים היא אינדיקציה לכריתת שקדים?', ['2 אירועים של דלקת שקדים','אירוע של אבצס פריטונסילרי','מעל 7 אירועי דלקת שקדים בשנה האחרונה','דום נשימה בשינה'],2,'לפי קריטריוני Paradise שהוצגו בקורס, יותר מ־7 אירועים בשנה (או יותר מ־5 בשנה במשך שנתיים, או יותר מ־3 בשנה במשך 3 שנים) הם התוויה. שימו לב: גם דום נשימה בשינה עם שקדים מוגדלים הוא התוויה מוכרת לאדנוטונסילקטומיה. התשובה שסומנה במקור היא ג׳, כנראה כי השאלה כוונה לדלקות חוזרות.', ['שני אירועים אינם מספיקים.','אירוע בודד של אבצס בדרך כלל אינו התוויה לכריתה. אבצסים חוזרים כן.','זו התשובה שסומנה במקור.','בפועל גם זו התוויה מוכרת (OSA עם היפרטרופיה של השקדים), אבל זו לא התשובה שסומנה.']],
 ['final-form-d',21,5,'איזה מהמקרים הבאים חשוד לדלף CSF?', ['מטופל בן 30 עם נזלת שקופה דו־צדדית, גודש אפי ושיעול מזה שבועיים','מטופל בן 32 עם נזלת שקופה דו־צדדית, גודש אפי, התעטשויות וגרד מזה כשנתיים','מטופלת בת 34, עודף משקל, הפרשה שקופה חד־צדדית לסירוגין בזמן ביצוע ולסלבה','מטופל בן 14 עם דימום אפי לסירוגין מצד ימין מזה כשנה'],2,'דלף CSF מתבטא בהפרשה מימית שקופה חד־צדדית, שמחמירה בהתכופפות או במאמץ (ולסלבה). אישה צעירה עם עודף משקל מתאימה לדלף ספונטני על רקע לחץ תוך־גולגולתי מוגבר אידיופתי. בירור: בדיקת beta-2 transferrin בהפרשה.', ['זו תמונה של זיהום ויראלי.','זו תמונה של נזלת אלרגית.','זו התשובה הנכונה.','דימום חד־צדדי חוזר במתבגר מעלה חשד לגידול (Juvenile angiofibroma), לא לדלף CSF.']],
 ['final-form-d',22,6,'מה נכון לגבי מחיצת האף?', ['סטיית מחיצת האף היא הסיבה המובילה לנחרה ודום נשימה בשינה','אספקת הדם למחיצת האף היא מסעיפים של INTERNAL + EXTERNAL CAROTID שהקצוות שלהם יוצרים פלקסוס בקדמת המחיצה','הטיפול בהמטומה של המחיצה הוא שמרני וכולל המתנה ואנלגטיקה בלבד','סיכויי הצלחה של ניתוח תיקון מחיצה הם סביב 60%'],1,'אזור קיסלבך בקדמת המחיצה הוא מקלעת של ענפים מה־ICA (anterior ethmoidal) ומה־ECA (sphenopalatine, greater palatine, superior labial). משם מגיעים רוב הדימומים מהאף.', ['סטיית מחיצה יכולה לתרום לחסימה, אבל היא אינה הסיבה המובילה לדום נשימה בשינה.','זו התשובה הנכונה.','המטומה ספטלית מחייבת ניקוז מהיר, כדי למנוע נמק של הסחוס, אבצס ואף אוכף.','שיעורי ההצלחה גבוהים יותר.']],
 ['final-form-d',23,6,'מה נכון לגבי periorbital cellulitis?', ['לרוב סיבוך של סינוסיטיס בסינוס הפרונטלי','בדיקת ההדמיה המועדפת שיש לבצע בעת אבחון פריאורביטל צלוליטיס היא MRI','גורם הסיכון המרכזי הוא דיכוי חיסוני','במידה ומתפתח אבצס, יש לשקול לבצע ניקוז בגישה אנדוסקופית או חיצונית'],3,'אבצס תת־פריאוסטלי או אורביטלי מנוקז, אם אין שיפור באנטיביוטיקה IV או אם יש פגיעה בראייה. הניקוז יכול להיות אנדוסקופי דרך האף או חיצוני. מקור הזיהום הוא לרוב הסינוסים האתמואידליים, וההדמיה הראשונה היא CT עם חומר ניגוד.', ['המקור השכיח הוא האתמואידים, דרך ה־lamina papyracea הדקה.','ההדמיה הראשונה היא CT. MRI משמש בחשד לסיבוך תוך־גולגולתי.','רוב המטופלים הם ילדים בריאים. דיכוי חיסוני אינו גורם הסיכון המרכזי.','זו התשובה הנכונה.']],
 ['final-form-d',24,6,'לאן מתנקז צינור הדמעות (Nasolacrimal duct)?', ['תחת הטורבינה העליונה','תחת הטורבינה האמצעית','תחת הטורבינה התחתונה','לתוך הסינוס המקסילרי'],2,'צינור הדמעות נפתח למיאטוס התחתון, מתחת לקונכייה התחתונה, דרך שסתום Hasner. במיאטוס האמצעי מתנקזים הסינוסים הפרונטלי, המקסילרי והאתמואידים הקדמיים.', ['למיאטוס העליון מתנקזים האתמואידים האחוריים.','למיאטוס האמצעי מתנקזים הסינוסים הפרונטלי והמקסילרי והאתמואידים הקדמיים.','זו התשובה הנכונה.','צינור הדמעות אינו מתנקז לסינוס.']],
 ['assaf-form-2',2,1,'מה מהבאים נכון לגבי הטיפול בהמטומה ספטלית של האף?', ['הטיפול המקובל הוא טמפונדה של האף לצורך עצירת הדימום','הטיפול דורש תרופות מעודדות קרישה דוגמת הקסקפרון (Tranexamic acid)','במידה ונשלל נזק נוסף, ניתן להסתפק בטיפול אנטיביוטי','הטיפול מחייב ניקוז של ההמטומה כולל השארת נקז','בילדים ניתן להסתפק במעקב בלבד'],3,'המטומה ספטלית מנתקת את הסחוס מאספקת הדם שמגיעה מהפריכונדריום. בלי ניקוז מהיר הסחוס עלול להינמק, ועלולים להתפתח אבצס, נקב ואף אוכף. הטיפול: חתך וניקוז, ואחר כך טמפונדה או נקז, כדי שהאוסף לא יתמלא שוב.', ['טמפונדה לבד, בלי ניקוז, לא פותרת את האוסף.','זה לא הטיפול. האוסף כבר קיים וצריך לנקז אותו.','אנטיביוטיקה לבד לא מספיקה. ההמטומה עצמה דורשת ניקוז.','זו התשובה הנכונה.','גם בילדים מנקזים בדחיפות, וסכנת עיוות האף אצלם גדולה במיוחד.']],
 ['assaf-form-2',3,1,'מה מהבאים אינו נכון לגבי Kiesselbach’s plexus?', ['90% מהדימומים מהאף מקורם מאזור זה, הנמצא בחלק האחורי של המחיצה','Anterior ethmoid artery נותן אספקת דם לאזור זה','Facial artery נותן אספקת דם לאזור זה','ניתן לטפל בדימום מאזור זה על ידי צריבה כימית','ניתן לטפל בדימום מאזור זה על ידי צריבה חשמלית'],0,'אזור קיסלבך (Little’s area) נמצא בחלק הקדמי־תחתון של המחיצה, לא בחלק האחורי. משם מגיעים כ־90% מהדימומים, והוא נגיש לצריבה כימית או חשמלית. דימום אחורי מגיע מאזור Woodruff.', ['זו הטענה השגויה: האזור קדמי, לא אחורי.','נכון. ה־anterior ethmoid (מה־ICA) תורם למקלעת.','נכון. ה־facial artery תורם דרך ה־superior labial.','נכון.','נכון.']],
 ['assaf-form-2',5,1,'מה מהבאים אינו נכון לגבי קשר לימפה מוגדל בצוואר?', ['במבוגרים מעל גיל 40, כ־80% מהקשרים בצוואר שאינם מבלוטת המגן הם ממאירים','מיקום גרורות בקשרי לימפה בצוואר יכול להצביע על מיקום הגידול הראשוני','בילדים לרוב הטיפול הראשוני בקשר לימפה צווארי מוגדל הוא אנטיביוטי','קשר לימפה צווארי מוגדל בנוכחות תפליט איפסילטרלי חד־צדדי באוזן התיכונה מחייב ניקור של עור התוף','במקרה של קשר לימפה צווארי מוגדל, הבדיקה האבחנתית המועדפת היא ניקור מחט עדינה (FNA)'],3,'קשר צווארי עם נוזל חד־צדדי באוזן התיכונה במבוגר מעלה חשד לגידול בנזופרינקס שחוסם את החצוצרה. הצעד הנדרש הוא בדיקה אנדוסקופית של הנזופרינקס וביופסיה, לא ניקור של עור התוף. שימו לב: במקור סומנה תשובה א׳, והמקור עצמו מציין שהתשובות אינן ודאיות. א׳ מבוססת על "כלל ה־80", שמקובל בספרות כהערכה גסה.', ['זו הערכה מקובלת ("כלל ה־80"), גם אם גסה. במקור סומנה תשובה זו.','נכון. כל רמה מתנקזת מאזור מסוים.','נכון. בילדים רוב הקשרים תגובתיים או זיהומיים.','זו הטענה השגויה: נדרש בירור של הנזופרינקס, לא ניקור.','נכון. FNA הוא כלי האבחון הראשון.']],
 ['assaf-form-2',6,1,'מבין הבאים, מהו אינו סיבוך אפשרי של תסמונת דום נשימה בילדים?', ['דלקות אוזן תיכונה חוזרות','עיכוב בגדילה','קשיי ריכוז','הרטבות לילה','יל״ד ריאתי'],0,'דום נשימה חסימתי בשינה בילדים עלול לגרום לעיכוב בגדילה, לבעיות קשב, ריכוז והתנהגות, להרטבת לילה, ובמקרים קשים ליתר לחץ דם ריאתי ול־cor pulmonale. דלקות אוזן חוזרות קשורות לאדנואידים מוגדלים, אבל אינן סיבוך של דום הנשימה עצמו.', ['זו התשובה: זה לא סיבוך של דום הנשימה.','סיבוך מוכר.','סיבוך מוכר.','סיבוך מוכר.','סיבוך מוכר במקרים קשים.']],
 ['assaf-form-2',7,1,'מה נכון בקשר ליבלות (קשריות) על מיתרי הקול (vocal cord nodules)?', ['היבלות בדרך כלל חד־צדדיות וממוקמות בין השליש האמצעי והקדמי של המיתר האמיתי','בסטרובוסקופיה נראית הפרעה בגל הרטט של ה־vocal ligament באיזור היבלת','הטיפול הוא ניתוחי: כריתה על ידי לייזר או סכין','שימוש יתר כרוני ממושך בקול יכול לגרום להופעת יבלות','פוגעות ב־1% מכלל הילדים, בנות יותר מבנים, אך בגיל ההתבגרות בנים יותר מבנות'],3,'קשריות נוצרות משימוש יתר כרוני בקול (מורים, זמרים, ילדים שצועקים). הן דו־צדדיות וסימטריות, בצומת השליש הקדמי והאמצעי, והטיפול הראשון הוא קלינאות תקשורת.', ['קשריות הן דו־צדדיות. נגע חד־צדדי מתאים יותר לפוליפ.','הנגע שטחי ובדרך כלל לא פוגע ב־vocal ligament.','הטיפול הראשון הוא תרפיה קולית, לא ניתוח.','זו התשובה הנכונה.','בילדים קשריות שכיחות יותר בבנים.']],
 ['assaf-form-2',8,1,'מהם גורמי סיכון לממאירות ראש צוואר מסוג הגרון והלוע?', ['עישון, אלכוהול, אנשים שמשתמשים בקולם לעבודה (זמרים וכו׳)','עישון, אנשים שמשתמשים בקולם לעבודה (זמרים וכו׳), מוצא אסייתי','עישון, אלכוהול, חשיפה לקרינה, HPV','עישון, HPV, מוצא אסייתי, אלרגיה','עישון, אלרגיה, חשיפה לקרינה'],2,'גורמי הסיכון העיקריים ל־SCC של הלוע והגרון: עישון ואלכוהול (שמגבירים זה את זה), HPV (במיוחד בגידולי אורופרינקס) וחשיפה לקרינה. שימוש מקצועי בקול גורם לקשריות, לא לסרטן. מוצא אסייתי ו־EBV קשורים לסרטן הנזופרינקס.', ['שימוש בקול אינו גורם סיכון לממאירות.','שימוש בקול אינו גורם סיכון, ומוצא אסייתי קשור לנזופרינקס.','זו התשובה הנכונה.','אלרגיה אינה גורם סיכון.','אלרגיה אינה גורם סיכון.']],
 ['assaf-form-2',9,1,'איזו תשובה נכונה בקשר ל־squamous cell carcinoma של הלרינקס?', ['גידולים גלוטיים הם אגרסיביים מקומית ושולחים גרורות לבלוטות בצוואר בשלב מוקדם','המיקום השכיח ביותר לממאירות הלרינקס הוא תת־גלוטיס עם פרוגנוזה הכי גרועה','ההתסמנות הראשונית הנפוצה ביותר לממאירות בגרון היא קוצר נשימה וסטרידור','צרידות חדשה או שינוי בצרידות בחולה מעשן מעל שבועיים מחייבת בדיקת לרינקס','סיכויי החלמה בטיפול בגידול T1–2 על ידי ניתוח או קרינה דומים והם 50–65%'],3,'אותה שאלה מופיעה גם במבחן הסיום (נוסח ד׳). צרידות מתמשכת במעשן היא דגל אדום ומחייבת לראות את הלרינקס. הגלוטיס הוא האתר השכיח, והגידולים בו מתגלים מוקדם בגלל הצרידות. ניקוז הלימפה שם מועט.', ['גידולים גלוטיים שולחים גרורות צוואריות מאוחר.','הגלוטיס הוא המיקום השכיח. תת־גלוטיס הוא הנדיר.','הסימן הראשון השכיח הוא צרידות.','זו התשובה הנכונה.','בגידול גלוטי מוקדם שיעורי ההחלמה גבוהים בהרבה.']],
 ['assaf-form-2',13,2,'מה מהבאים אינו תסמין אופייני לשיתוק חד־צדדי של מיתר קול?', ['צרידות','קוצר נשימה בדיבור','קוצר נשימה במאמץ גופני','שיעול בזמן שתייה או אכילה','קושי בפינוי הפרשות מדרכי הנשימה'],2,'בשיתוק חד־צדדי הגלוטיס לא נסגר עד הסוף: קול צרוד ונשיפתי, קוצר נשימה בדיבור, אספירציה עם שיעול בשתייה, ושיעול חלש שמקשה לפנות הפרשות. נתיב האוויר עצמו לרוב מספיק, ולכן קוצר נשימה במאמץ אינו אופייני. הוא אופייני לשיתוק דו־צדדי. שימו לב: במקור סומנה תשובה ה׳, והמקור מציין שהתשובות אינן ודאיות. במבחן הסיום (נוסח ד׳) נשאלה שאלה דומה, ושם סומן "קוצר נשימה במאמץ".', ['אופייני.','אופייני, בגלל בריחת אוויר.','זו התשובה: קוצר נשימה במאמץ אופייני לשיתוק דו־צדדי.','אופייני, בגלל אספירציה.','אופייני, בגלל שיעול חלש. במקור סומנה תשובה זו.']],
 ['assaf-form-2',16,2,'מה מהבאים אינו מהווה גורם סיכון לדלקת אוזן חיצונית?', ['חשיפה למי בריכה או ים','הרכבת מכשיר שמיעה','הימצאות גוף זר','ניקוי אוזניים בצמרון (מקל אוזניים)','סינוסיטיס חוזרת'],4,'גורמי סיכון לדלקת אוזן חיצונית: לחות (שחייה), פגיעה בעור התעלה (מקלוני אוזניים, גירוד) וחסימה או גירוי (מכשיר שמיעה, אטמים, גוף זר). לסינוסיטיס אין קשר לתעלת השמע החיצונית.', ['גורם סיכון קלאסי ("אוזן של שחיינים").','גורם סיכון: לחות וגירוי בתעלה.','גורם סיכון.','גורם סיכון: פגיעה בעור ובשכבת הצרומן המגינה.','זו התשובה.']],
 ['assaf-form-2',18,2,'מה מהבאים אינו נכון לגבי דלקת אוזן תיכונה?', ['רוב הילדים חווים לפחות פעם אחת בילדותם דלקת באוזן תיכונה','שיא שכיחות דלקות באוזן תיכונה הוא בגיל 6–12 חודשים','חשיפה לעישון היא אחד מגורמי הסיכון למחלה','המופילוס אינפלואנזה הוא המזהם החיידקי השכיח ביותר','אמוקסיצילין הוא קו ראשון לטיפול בדלקת אוזן תיכונה'],3,'במצגת הקורס S. pneumoniae מופיע ראשון ברשימת הגורמים, לפני H. influenzae ו־M. catarrhalis. בעידן החיסון לפנאומוקוק עלה מקומו של H. influenzae לא טיפוס, ולכן הנושא שנוי במחלוקת. המקור מציין שהתשובות אינן ודאיות.', ['נכון.','נכון בקירוב. השיא הוא בשנה–שנתיים הראשונות.','נכון.','זו התשובה שסומנה. במצגת פנאומוקוק מוצג כגורם המוביל.','נכון.']],
 ['assaf-form-2',19,2,'מה מהבאים אינו אחד המאפיינים של כולסטאטומה קונגניטלית?', ['מסה לבנה מדיאלית לעור תוף תקין','ללא רקע של ניתוח אוזן','לילד היסטוריה של הפרשות מהאוזן','נוכחות קרטין באוזן התיכונה','מראה תקין של ה־pars tensa וה־pars flaccida'],2,'כולסטאטומה מולדת היא מסה לבנה מאחורי עור תוף שלם ותקין, בילד בלי היסטוריה של ניתוח, נקב או דלקות והפרשות מהאוזן. היסטוריה של הפרשות מתאימה לכולסטאטומה נרכשת.', ['מאפיין.','מאפיין.','זו התשובה: זה מאפיין של כולסטאטומה נרכשת.','מאפיין: הכולסטאטומה עצמה היא קרטין.','מאפיין: עור התוף תקין.']],
 ['assaf-form-2',20,2,'מה מהבאים אינו סיבוך אפשרי לכולסטאטומה?', ['אבצס אפידורלי','מסטואידיטיס','שיתוק עצב הפנים','פיסטולה לברינטית','כל התשובות לעיל הן סיבוך אפשרי לכולסטאטומה'],4,'כולסטאטומה הורסת עצם ויכולה לגרום לסיבוכים בכל הכיוונים: מסטואידיטיס, פיסטולה לבירינתית (חשיפת התעלה הצידית), שיתוק עצב הפנים, וסיבוכים תוך־גולגולתיים כמו אבצס אפידורלי, מנינגיטיס ואבצס מוחי.', ['סיבוך אפשרי.','סיבוך אפשרי.','סיבוך אפשרי.','סיבוך אפשרי.','זו התשובה: כולם סיבוכים אפשריים.']],
 ['assaf-form-2',21,2,'מה היא הסיבה השכיחה ביותר לנקב בעור התוף?', ['דלקות חוזרות של אוזן תיכונה','מצב לאחר צינוריות אוורור (כפתורים)','טראומה מקומית','שבר בעצם טמפורלית','חשיפה לרעש עז או הדף'],0,'הגורם השכיח לנקב בעור התוף הוא זיהום: AOM שגורם לקרע, ודלקות חוזרות שמשאירות נקב כרוני. שאר הגורמים קיימים אבל פחות שכיחים.', ['זו התשובה הנכונה.','אפשרי, אבל פחות שכיח.','אפשרי, אבל פחות שכיח.','אפשרי, אבל פחות שכיח.','אפשרי, אבל פחות שכיח.']],
 ['assaf-form-2',22,2,'מה מהבאים הוא צירוף התסמינים האופייני ביותר לסינוסיטיס חדה (acute sinusitis)?', ['חום, כאבים בפנים/ראש, נזלת, שיעול יבש','חום, כאבי אוזניים, אטימות אפית, נזלת','חום, כאבי אוזניים, נזלת, שיעול ליחתי','כאבים בפנים/ראש, אטימות אפית, נזלת, שיעול ליחתי','כאבי אוזניים, אטימות אפית, נזלת, שיעול יבש'],3,'הקריטריונים לסינוסיטיס: חסימה אפית, הפרשה (קדמית או אחורית, ולכן שיעול ליחתי מטפטוף אחורי), כאב או לחץ בפנים, וירידה בחוש הריח. כאבי אוזניים וחום אינם חלק מההגדרה.', ['חסרה חסימה אפית, ושיעול יבש פחות אופייני.','כאבי אוזניים אינם תסמין מרכזי.','כאבי אוזניים אינם תסמין מרכזי.','זו התשובה הנכונה.','כאבי אוזניים ושיעול יבש אינם אופייניים.']],
 ['assaf-form-2',23,2,'מה מהבאים אינו נכון לגבי Warthin’s tumor?', ['גידול ממאיר של בלוטות הרוק','10–20% מגידולי בלוטת הפרוטיד','מתאפיין במסה שאינה כואבת וגדלה באיטיות','ב־10% מהמקרים הגידול דו־צדדי','אופייני לגברים מבוגרים מעשנים'],0,'גידול Warthin הוא גידול שפיר (השני בשכיחותו בפרוטיד אחרי pleomorphic adenoma). הוא אופייני לגברים מבוגרים מעשנים, מתבטא בגוש לא כואב שגדל לאט, ולעתים הוא דו־צדדי או רב־מוקדי.', ['זו התשובה: הגידול שפיר.','נכון בקירוב.','נכון.','נכון. זה גידול הפרוטיד השכיח ביותר שמופיע דו־צדדי.','נכון.']],
 ['assaf-form-2',25,2,'קוניוטומיה (קריקו־תירוטומיה) היא פעולה להשגת נתיב אוויר בגישה צווארית במקרה חירום שבו לא ניתן להגיע לנתיב אוויר בגישה אחרת. מה מהבאים אינו נכון לגבי קוניוטומיה?', ['במהלך הפעולה יש ליצור פתח לנתיב האוויר דרך הממברנה שבין סחוס הקריקואיד לסחוס התירואיד','הממברנה לביצוע קוניוטומיה ממוקמת מיד מתחת לסחוס הקריקואיד','מיתרי הקול נמצאים בתוך סחוס התירואיד','לרוב סחוס הקריקואיד הוא הסחוס הבולט יותר במישוש סחוסי הגרון בנשים','הקריקואיד הוא הטבעת הסחוסית המלאה היחידה בנתיב האוויר'],1,'ה־cricothyroid membrane נמצאת בין סחוס התירואיד (מעל) לסחוס הקריקואיד (מתחת), כלומר מעל הקריקואיד ולא מתחתיו. מתחת לקריקואיד מתחיל הקנה.', ['נכון.','זו הטענה השגויה: הממברנה נמצאת מעל הקריקואיד.','נכון.','מקובל: בנשים בליטת התירואיד פחות בולטת.','נכון.']],
 ['final-form-d',1,1,'מה נכון לגבי כואנל אטרזיה?', ['רואים זאת אחת ל־100 לידות','יותר נפוץ דו־צדדי','בדרך כלל מופיע בשילוב של חסימה ממברנוטית וגרמית','נפוץ יותר בבנים'],2,'אטרזיה כואנלית היא חסימה מולדת של הפתחים האחוריים של האף. לרוב החסימה משולבת, גרמית וממברנוטית. רוב המקרים חד־צדדיים, והיא נדירה (כאחת ל־5,000–8,000 לידות) ושכיחה יותר בבנות. אטרזיה דו־צדדית מתבטאת ביילוד במצוקה נשימתית שמשתפרת בבכי, כי יילודים נושמים דרך האף.', ['השכיחות נמוכה בהרבה, כאחת ל־5,000–8,000 לידות.','רוב המקרים חד־צדדיים.','זו התשובה הנכונה.','שכיחה יותר בבנות.']],
 ['final-form-d',3,1,'סטרידור אינספירטורי שהחל בשבועות הראשונים לחיים, מחמיר עם אוכל, בשינה או כאשר התינוק לא רגוע. באיזה גובה בדרכי האוויר נמצאת החסימה?', ['סופרהגלוטי (מעל לגובה מיתרי הקול)','גלוטי (בגובה מיתרי הקול)','סבגלוטי (מתחת לגובה מיתרי הקול)','ברונכוסים'],0,'זו התמונה של לרינגומלציה, הגורם השכיח לסטרידור מולד. רקמות סופראגלוטיות רכות קורסות פנימה בשאיפה, ולכן הסטרידור שאיפתי ומחמיר בהאכלה, בבכי ובשכיבה על הגב. סטרידור שאיפתי ממקם את החסימה מעל הגלוטיס או בגובהו.', ['זו התשובה הנכונה.','חסימה גלוטית, למשל שיתוק מיתרים, גורמת לסטרידור שאיפתי או דו־פאזי, אבל לא עם הדפוס הזה.','חסימה סובגלוטית גורמת בדרך כלל לסטרידור דו־פאזי.','חסימה בברונכים גורמת לצפצופים נשיפתיים.']],
 ['final-form-d',5,2,'איזה מהבאים מסירים (באופן חלקי) בעת ניתוח להוצאת Thyroglossal duct cyst?', ['Hyoid bone','Mandible bone','Sternum bone','Thyroid cartilage'],0,'ניתוח Sistrunk כולל כריתה של הציסטה, של החלק האמצעי של עצם ההיואיד ושל המסלול עד בסיס הלשון. כך יורד שיעור החזרה מכ־50% לכמה אחוזים בלבד.', ['זו התשובה הנכונה.','הלסת אינה חלק מהמסלול.','עצם החזה אינה חלק מהמסלול.','סחוס התירואיד אינו נכרת.']],
 ['final-form-d',7,2,'בימים הראשונים אחרי ניתוח לכריתה שלמה של בלוטת התריס, אחרי איזו בדיקת דם חשוב לעקוב?', ['קריאטינין','נתרן','ספירת דם לבנה','סידן','אשלגן'],3,'אחרי כריתה מלאה של בלוטת התריס עלולה להיפגע אספקת הדם לבלוטות הפאראתירואיד, או שהן יוסרו בטעות. לכן עוקבים אחרי סידן (ולעתים PTH) כדי לזהות היפוקלצמיה. מחפשים גם סימנים כמו נימול סביב הפה ו־Chvostek/Trousseau.', ['אין סיבה מיוחדת לעקוב אחרי תפקודי כליה.','לא קשור ישירות לניתוח.','לא המדד העיקרי אחרי כריתת תירואיד.','זו התשובה הנכונה.','לא קשור ישירות לניתוח.']],
 ['final-form-d',8,2,'הבירור הראשוני לגוש בבלוטת התריס יכלול:', ['CT צוואר עם חומר ניגוד','מיפוי יוד','CT או US צוואר וביצוע ביופסיה פתוחה על פי הממצאים','US צוואר והחלטה על FNA לפי תוצאות ה־US'],3,'לפי ATA: אנמנזה, בדיקה ו־TSH, אחר כך US. המאפיינים בסונר (מיקרו־הסתיידויות, שוליים לא סדירים, היפואקואיות, taller than wide) והגודל קובעים אם לבצע FNA. מיפוי יוד שמור למצב של TSH נמוך.', ['CT אינו הבדיקה הראשונה לקשרית.','מיפוי מתאים רק כש־TSH מדוכא, כדי לזהות קשרית חמה.','ביופסיה פתוחה אינה חלק מהבירור הראשוני.','זו התשובה הנכונה.']],
 ['final-form-d',11,3,'איזו מהסיבוכים התוך־גולגולתיים הבאים עלול להתרחש בדלקת אוזן תיכונה חריפה?', ['מסטואידיטיס','שיתוק עצב הפנים','דלקת במבוך האוזן (לבירינטיטיס)','ירידת שמיעה הולכתית','דלקת קרום המוח'],4,'סיבוכי AOM מתחלקים לחוץ־גולגולתיים (מסטואידיטיס, שיתוק עצב הפנים, לבירינתיטיס, אבצס Bezold) ולתוך־גולגולתיים (מנינגיטיס, אבצס אפידורלי, תת־דורלי או מוחי, תרומבוזיס של הסינוס, otitic hydrocephalus).', ['סיבוך חוץ־גולגולתי.','סיבוך חוץ־גולגולתי, בתוך עצם הרקה.','סיבוך חוץ־גולגולתי.','זו תוצאה של הנוזל באוזן, לא סיבוך תוך־גולגולתי.','זו התשובה הנכונה.']],
 ['final-form-d',12,3,'איזה מהממצאים באוטוסקופיה הוא העקבי ביותר עם דלקת אוזן תיכונה חריפה?', ['שקיעה (רטרקציה) של עור התוף','פלס אוויר־נוזל מאחורי קרום התוף','נקב בקרום התוף','בלט ואודם של עור התוף','פקק שעווה (צרומן) באוזן'],3,'הממצא הספציפי ביותר ל־AOM הוא עור תוף בולט (bulging), לרוב אדום ולא זז בפנאומטוסקופיה, כי מוגלה מצטברת מאחוריו.', ['רטרקציה מתאימה לתפקוד לקוי של החצוצרה או ל־OME.','פלס אוויר־נוזל מתאים ל־OME (נוזל בלי דלקת חריפה).','נקב יכול להיות סיבוך, אבל הוא לא הממצא העקבי.','זו התשובה הנכונה.','שעווה אינה קשורה ל־AOM.']],
 ['final-form-d',14,4,'מה מהבאים נכון לגבי סחרחורת פריפרית מסוג ורטיגו התקפי תנוחתי שפיר (Benign Paroxysmal Positional Vertigo, BPPV)?', ['הסוג השכיח ביותר נגרם עקב מעורבות של ה־superior (anterior) semicircular canal','אופייני הופעה של ניד (ניסטגמוס) במבחן Dix-Hallpike שאינו מתעייף בחזרה על המבחן','בעקבות גירוי של התעלה הסמיסרקולרית המעורבת מופיע התקף סחרחורת למשך כחצי שעה בכל פעם','הסחרחורת ב־BPPV מלווה בירידת שמיעה חולפת','קו הטיפול הראשוני הוא פיזיותרפיה'],4,'הטיפול הראשון ב־BPPV הוא תמרוני החזרה של חלקיקים (כמו Epley) ושיקום וסטיבולרי, שמבוצעים על ידי רופא או פיזיותרפיסט. התעלה המעורבת לרוב היא האחורית. הניד נחלש בחזרות, ההתקף נמשך שניות, ואין ירידת שמיעה.', ['התעלה השכיחה היא האחורית.','הניד ב־BPPV מתעייף בחזרות.','ההתקפים נמשכים שניות, עד דקה.','אין ירידת שמיעה ב־BPPV.','זו התשובה הנכונה.']],
 ['final-form-d',15,4,'החיידק השכיח ביותר בדלקת אוזן חיצונית הינו:', ['סטאפ אוריאוס','פסאודומונס אוריגנוזה','אנטרוקוקוס','סטאפ אפידרמידיס','פניאומוקוק'],1,'Pseudomonas aeruginosa הוא הגורם השכיח ביותר לדלקת אוזן חיצונית חריפה, ואחריו Staphylococcus aureus.', ['שני בשכיחותו.','זו התשובה הנכונה.','לא גורם שכיח.','חלק מהפלורה הרגילה של העור.','גורם של דלקת אוזן תיכונה.']],
 ['final-form-d',16,4,'מה נכון בקשר ליבלות על מיתרי הקול (vocal cord nodules)?', ['היבלות בדרך כלל חד־צדדיות או אסימטריות','הטיפול הוא ניתוחי (כריתה על ידי לייזר או סכין מיקרוכירורגית)','אופייני שימוש יתר כרוני ממושך בקול, ולא שימוש טראומתי אקוטי בקול','פוגעות ב־1% מכלל הילדים, בנות יותר מבנים, אך בגיל ההתבגרות בנים יותר מבנות'],2,'קשריות נוצרות משימוש יתר כרוני בקול. הן דו־צדדיות וסימטריות, והטיפול הראשון הוא תרפיה קולית. נגע חד־צדדי אחרי מאמץ קולי חד מתאים יותר לפוליפ.', ['קשריות דו־צדדיות וסימטריות.','הטיפול הראשון הוא קלינאות תקשורת.','זו התשובה הנכונה.','בילדים קשריות שכיחות יותר בבנים, ובגיל ההתבגרות ובמבוגרים יותר בנשים, כלומר הפוך ממה שכתוב.']],
 ['final-form-d',25,6,'בן שנתיים מגיע למיון עם הוריו בשל הפרשה מוגלתית מצחינה מזה כשבוע מנחיר ימין, ללא חום או תלונות נוספות. מהי האבחנה הסבירה ביותר?', ['דיכוי חיסוני','גוף זר','המטומה ספטלית','דלף CSF','סינוסיטיס ספנואידלית'],1,'הפרשה חד־צדדית, מוגלתית ומצחינה בפעוט היא גוף זר באף עד שיוכח אחרת. מוציאים מהר, כי יש סכנת שאיפה, זיהום ונקב במחיצה, ובמיוחד בסוללת כפתור.', ['דיכוי חיסוני לא יגרום לתמונה חד־צדדית כזו.','זו התשובה הנכונה.','המטומה מופיעה אחרי חבלה, עם חסימה וכאב.','דלף CSF הוא הפרשה שקופה, לא מוגלתית.','סינוסיטיס ספנואידלית נדירה בגיל הזה ולא תתבטא כך.']],
 ['assaf-form-2',1,1,'להיכן מתנקז ה־nasolacrimal duct?', ['מיאטוס אמצעי','מיאטוס תחתון','אתמואידים קידמיים','סינוס מקסילרי','רצס פרונטואתמואידלי'],1,'צינור הדמעות נפתח למיאטוס התחתון, מתחת לקונכייה התחתונה. במיאטוס האמצעי מתנקזים הסינוסים הפרונטלי, המקסילרי והאתמואידים הקדמיים.', ['כאן מתנקזים הסינוסים הפרונטלי, המקסילרי והאתמואידים הקדמיים.','זו התשובה הנכונה.','האתמואידים הם סינוסים, לא מקום ניקוז של צינור הדמעות.','צינור הדמעות אינו מתנקז לסינוס.','זה מסלול הניקוז של הסינוס הפרונטלי.']],
 ['assaf-form-2',4,1,'מה מהבאים הוא הנכון ביותר לגבי ציסטה תירוגלוסלית (TGDC)?', ['זוהי המסה הצווארית המולדת השנייה בשכיחותה','לפני ניתוח לכריתת ציסטה תירוגלוסלית יש לבצע בדיקת דם לרמות TSH','מדובר בגידול הצווארי השכיח ביותר בילדים','לעיתים הציסטה מכילה את רקמת בלוטת התריס היחידה בגוף','כריתה של הציסטה לבדה משיגה ריפוי מלא בכ־90% מהמקרים'],3,'לפעמים רקמת התריס היחידה בגוף נמצאת בתוך הציסטה או לאורך המסלול. לכן לפני הניתוח מבצעים US (לפי הצורך גם מיפוי), כדי לוודא שיש בלוטה במקומה. הניתוח הנכון הוא Sistrunk, כי כריתת הציסטה לבדה גורמת לשיעור חזרה גבוה.', ['TGDC היא המסה הצווארית המולדת השכיחה ביותר, לא השנייה.','הבדיקה החשובה לפני הניתוח היא הדמיה (US). TSH לבדו לא עונה על השאלה.','בילדים גושים צוואריים תגובתיים או זיהומיים שכיחים יותר.','זו התשובה הנכונה.','כריתת הציסטה לבדה גורמת לשיעור חזרה גבוה (כ־50%). ניתוח Sistrunk מוריד אותו מאוד.']],
 ['assaf-form-2',10,1,'מה מהבאים נכון לגבי סחרחורת פריפרית מסוג Benign Paroxysmal Positional Vertigo (BPPV)?', ['הסוג השכיח ביותר נגרם עקב מעורבות של ה־superior (anterior) semicircular canal','אופייני הופעה של ניד (ניסטגמוס) במבחן Dix-Hallpike שאינו מתעייף בחזרה על המבחן','בעקבות גירוי של התעלה הסמיסרקולרית המעורבת מופיע התקף סחרחורת למשך כחצי שעה בכל פעם','הסחרחורת ב־BPPV מלווה בירידת שמיעה חולפת','קו הטיפול הראשוני הוא פיזיותרפיה'],4,'אותה שאלה מופיעה גם במבחן הסיום (נוסח ד׳). הטיפול הראשון הוא תמרוני החזרה (Epley) ושיקום וסטיבולרי. התעלה השכיחה היא האחורית, הניד מתעייף, ההתקף נמשך שניות, ואין ירידת שמיעה.', ['התעלה השכיחה היא האחורית.','הניד מתעייף בחזרות.','ההתקפים נמשכים שניות.','אין ירידת שמיעה.','זו התשובה הנכונה.']],
 ['assaf-form-2',11,2,'איזו תשובה לא נכונה בקשר ל־Meniere’s Disease?', ['מתאפיינת בהתקפים עזים של סחרחורת','התקפי הסחרחורת נמשכים שעות בכל פעם','מתאפיינת בליקוי שמיעתי הולכתי, אשר מחמיר ומשתפר במחזוריות','סימנים מבשרים הם תחושת אטימות ורעש גובר באוזן','זאת מחלה שבדרך כלל מערבת את המרכיב הקוכלארי והווסטיבולרי של האוזן הפנימית'],2,'במנייר הירידה בשמיעה היא תחושתית־עצבית ולא הולכתית. בהתחלה היא בתדרים נמוכים ומשתנה, ובהמשך מתקדמת. ההתקפים נמשכים דקות עד שעות, ומלווים בטינטון ובמלאות באוזן.', ['נכון.','נכון.','זו הטענה השגויה: הירידה תחושתית־עצבית.','נכון.','נכון: המחלה מערבת את השבלול ואת המערכת הווסטיבולרית.']],
 ['assaf-form-2',12,2,'מה לא נכון לגבי Vestibular Neuronitis?', ['המחלה מתאפיינת באירוע פתאומי של סחרחורת ללא סימנים מבשרים','המחלה היא מחלה חד־צדדית, ומערבת את האיברים הווסטיבולרי והקוכלארי','המחלה יכולה להמשך שעות עד ימים','הטיפול במחלה הוא סימפטומטי בלבד','המחלה מיוחסת לאטיולוגיה ויראלית'],1,'נויריטיס וסטיבולרית פוגעת בעצב הווסטיבולרי בלבד, ולכן השמיעה תקינה. כשיש גם ירידת שמיעה, האבחנה היא לבירינתיטיס. הטיפול תומך, ושיקום וסטיבולרי מוקדם עוזר. יש מי שנותנים גם סטרואידים בשלב מוקדם.', ['נכון.','זו הטענה השגויה: השבלול לא מעורב.','נכון.','נכון במסגרת הקורס: טיפול תומך ושיקום.','נכון.']],
 ['assaf-form-2',14,2,'מבין הבאים, מהו הגידול הממאיר השכיח ביותר בבלוטת המגן?', ['גידול פוליקולרי','גידול פפילרי','גידול מדולרי','גידול אנפלסטי','לימפומה'],1,'קרצינומה פפילרית מהווה כ־80% מסרטני בלוטת התריס. היא מתפשטת בעיקר לקשרי לימפה, והפרוגנוזה שלה מצוינת.', ['כ־15%.','זו התשובה הנכונה.','כ־5%.','פחות מ־2%.','נדיר.']],
 ['assaf-form-2',15,2,'מה אינו נכון לגבי היפרפאראתירואידיזם ראשוני?', ['כ־85% מהמקרים הם תוצאה של אדנומה בודדת','קרצינומה של הפאראתירואיד היא אתיולוגיה אפשרית','ערכי סידן מעל 14 מהווים סכנת חיים','אופייני שרמות הסידן בשתן נמוכות','הימצאות אבנים בכליות בנוכחות היפרפאראתירואידיזם ראשוני מהווה אינדיקציה לניתוח'],3,'בהיפרפאראתירואידיזם ראשוני הסידן בשתן תקין או גבוה (היפרקלציאוריה), ולכן יש אבנים בכליות. סידן נמוך בשתן עם סידן גבוה בדם מכוון ל־FHH (היפרקלצמיה היפוקלציאורית משפחתית), שאינה מטופלת בניתוח.', ['נכון.','נכון, אם כי נדיר (פחות מ־1%).','נכון: משבר היפרקלצמי.','זו הטענה השגויה.','נכון: לפי קריטריוני NIH.']],
 ['assaf-form-2',17,2,'החיידק השכיח ביותר בדלקת אוזן חיצונית הינו:', ['סטאפ אוריאוס','פסאודומונס אוריגנוזה','אנטרוקוקוס','סטאפ אפידרמידיס','פניאומוקוק'],1,'אותה שאלה מופיעה גם במבחן הסיום. Pseudomonas aeruginosa הוא הגורם השכיח ביותר, ואחריו Staphylococcus aureus.', ['שני בשכיחותו.','זו התשובה הנכונה.','לא גורם שכיח.','חלק מהפלורה הרגילה.','גורם של AOM.']],
 ['assaf-form-2',24,2,'מה מהבאים אינו סימן של אבצס פריטונסילרי?', ['דחיקה של הענבל','הגדלה א־סימטרית של אחד השקדים','Muffled voice','טריזמוס','בלט חך'],4,'שימו לב: כל חמש האפשרויות הן בעצם סימנים מוכרים של אבצס פריטונסילרי. יש סטיית ענבל לצד הנגדי, שקד שנדחק מדיאלית, קול "תפוח אדמה לוהט", טריזמוס, ובלט של החך הרך מעל השקד. במקור סומנה תשובה ה׳, והמקור מציין שהתשובות אינן ודאיות. ייתכן שבשחזור נפלה טעות בניסוח האפשרויות.', ['סימן מוכר: הענבל נדחק לצד הנגדי.','סימן מוכר.','סימן מוכר.','סימן מוכר: גירוי של שריר ה־medial pterygoid.','זו התשובה שסומנה במקור, אבל בלט של החך הרך הוא דווקא סימן קלאסי של האבצס.']]
];

